import 'dotenv/config';
import express, { type NextFunction, type Request, type Response } from 'express';
import helmet from 'helmet';
import cors from 'cors';
import rateLimit from 'express-rate-limit';
import { Pool } from 'pg';
import { createCipheriv, createDecipheriv, createHash, createHmac, randomBytes, randomInt, randomUUID, scrypt as scryptCb, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';

const scrypt = promisify(scryptCb);
const port = Number(process.env.PORT || 3000);
const maxAge = 30 * 24 * 60 * 60 * 1000;
const production = process.env.NODE_ENV === 'production';
const pool = process.env.DATABASE_URL ? new Pool({ connectionString: process.env.DATABASE_URL, ssl: process.env.PGSSLMODE === 'require' ? { rejectUnauthorized: true } : undefined, max: 10, connectionTimeoutMillis: 5000 }) : null;
const app = express();
// Railway terminates TLS and forwards one trusted proxy hop; configure Express so
// express-rate-limit can resolve client IPs without trusting arbitrary proxy chains.
app.set('trust proxy', 1);
app.disable('x-powered-by');
const allowedOrigins=String(process.env.CORS_ORIGIN||'').split(',').map(value=>value.trim()).filter(Boolean);
app.use(cors({origin:(origin,callback)=>{if(!origin||allowedOrigins.includes(origin))return callback(null,true);return callback(null,false);},credentials:true,methods:['GET','POST','PUT','DELETE','OPTIONS'],allowedHeaders:['Accept','Content-Type']}));
app.use(helmet());
app.use(express.json({ limit: '8mb', verify: (req, _res, buffer) => { (req as Request & { rawBody?: string }).rawBody = buffer.toString('utf8'); } }));
app.use(rateLimit({ windowMs: 60_000, limit: 180, standardHeaders: 'draft-7', legacyHeaders: false }));
// Versioned API alias: /api/v1/* maps to the same handlers as /api/* while preserving query strings.
app.use((req, _res, next) => { if (req.url === '/api/v1' || req.url.startsWith('/api/v1/')) req.url = '/api' + req.url.slice('/api/v1'.length); next(); });
const authRateLimit = rateLimit({ windowMs: 15 * 60_000, limit: 10, standardHeaders: 'draft-7', legacyHeaders: false, message: { error: 'Too many login or signup attempts. Please wait 15 minutes and try again.', code: 'SV-AUTH-429' } });
const languages = [{code:'en',label:'English'},{code:'es',label:'Spanish'},{code:'fr',label:'French'},{code:'de',label:'German'},{code:'it',label:'Italian'},{code:'pt',label:'Portuguese'},{code:'ja',label:'Japanese'},{code:'ko',label:'Korean'},{code:'zh',label:'Chinese'},{code:'ru',label:'Russian'},{code:'ar',label:'Arabic'},{code:'hi',label:'Hindi'},{code:'nl',label:'Dutch'},{code:'pl',label:'Polish'},{code:'tr',label:'Turkish'}];
type User = { id:string; email:string; username:string; preferredLanguage:string };
declare global { namespace Express { interface Request { svUser?: User } } }
const fail=(res:Response,status:number,code:string,message:string)=>res.status(status).json({error:message,code});
app.use((req,res,next)=>{const origin=String(req.headers.origin||'');if(origin&&['POST','PUT','DELETE','PATCH'].includes(req.method)&&allowedOrigins.length&&!allowedOrigins.includes(origin))return fail(res,403,'SV-CSRF-001','Request origin is not allowed.');next();});
const tokenHash=(token:string)=>createHash('sha256').update(token).digest('hex');
function tokenEncryptionKey(){const value=String(process.env.TOKEN_ENCRYPTION_KEY||'');if(!/^[a-f0-9]{64}$/i.test(value))throw new Error('TOKEN_ENCRYPTION_KEY must be configured as 64 hexadecimal characters.');return Buffer.from(value,'hex');}
function encryptToken(value:string){const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',tokenEncryptionKey(),iv);const encrypted=Buffer.concat([cipher.update(value,'utf8'),cipher.final()]);return 'enc:v1:'+iv.toString('hex')+':'+cipher.getAuthTag().toString('hex')+':'+encrypted.toString('hex');}
function decryptToken(value:string){if(!value.startsWith('enc:v1:'))throw new Error('Stored OAuth token is not encrypted; reconnect the platform after setting TOKEN_ENCRYPTION_KEY.');const [, ,ivHex,tagHex,dataHex]=value.split(':');const decipher=createDecipheriv('aes-256-gcm',tokenEncryptionKey(),Buffer.from(ivHex,'hex'));decipher.setAuthTag(Buffer.from(tagHex,'hex'));return Buffer.concat([decipher.update(Buffer.from(dataHex,'hex')),decipher.final()]).toString('utf8');}
function normalizeEmail(input:string){const v=input.trim().toLowerCase();const at=v.lastIndexOf('@');if(at<1)return v;const local=v.slice(0,at),domain=v.slice(at+1);return ['gmail.com','googlemail.com'].includes(domain)?local.split('+')[0].replace(/\./g,'')+'@gmail.com':v;}
const normalizeUsername=(s:string)=>s.trim().toLowerCase();
function cookie(req:Request,name:string){for(const part of (req.headers.cookie||'').split(';')){const [key,...value]=part.trim().split('=');if(key===name){try{return decodeURIComponent(value.join('='));}catch{return '';}}}return '';}
function setCookie(res:Response,token:string,age:number){res.setHeader('Set-Cookie',token? `streamvoice_session=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=${production?'None':'Lax'}; Max-Age=${Math.floor(age/1000)}${production?'; Secure':''}`:`streamvoice_session=; Path=/; HttpOnly; SameSite=${production?'None':'Lax'}; Max-Age=0${production?'; Secure':''}`);}
async function hashPassword(password:string,salt:string){const derived=await scrypt(password,Buffer.from(salt,'hex'),64) as Buffer;return derived.toString('hex');}
function equalHex(a:string,b:string){const x=Buffer.from(a,'hex'),y=Buffer.from(b,'hex');return x.length===y.length&&x.length>0&&timingSafeEqual(x,y);}
function equalText(a:string,b:string){const x=Buffer.from(a,'utf8'),y=Buffer.from(b,'utf8');return x.length===y.length&&timingSafeEqual(x,y);}
function needsDb(_req:Request,res:Response,next:NextFunction){if(!pool)return fail(res,503,'SV-DB-001','Database is not configured. Set DATABASE_URL in the server environment.');next();}
async function auth(req:Request,_res:Response,next:NextFunction){try{if(!pool)return next();const token=cookie(req,'streamvoice_session');if(!token||token.length>256)return next();const q=await pool.query('SELECT a.id,a.email,a.username,a.preferred_language,s.id AS session_id FROM sv_sessions s JOIN sv_accounts a ON a.id=s.user_id WHERE s.token_hash=$1 AND s.expires_at>now() AND a.deleted_at IS NULL LIMIT 1',[tokenHash(token)]);if(q.rowCount){const r=q.rows[0];req.svUser={id:r.id,email:r.email,username:r.username,preferredLanguage:r.preferred_language};await pool.query("UPDATE sv_sessions SET expires_at=now()+interval '30 days',updated_at=now() WHERE id=$1",[r.session_id]);}next();}catch(e){next(e);}}
async function newSession(userId:string){if(!pool)throw new Error('Database not configured');const token=randomBytes(32).toString('base64url');await pool.query("INSERT INTO sv_sessions(id,user_id,token_hash,expires_at) VALUES($1,$2,$3,now()+interval '30 days')",[randomUUID(),userId,tokenHash(token)]);return token;}
async function translateForUser(userId:string,text:string){const key=String(process.env.GOOGLE_TRANSLATE_API_KEY||'');if(!key||!pool)return text;try{const settings=await pool.query('SELECT enabled,language FROM sv_chat_settings WHERE user_id=$1',[userId]);const language=String(settings.rows[0]?.language||'en');if(!settings.rows[0]?.enabled||language==='en')return text;const response=await fetch('https://translation.googleapis.com/language/translate/v2?key='+encodeURIComponent(key),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({q:text,target:language,format:'text'})});if(!response.ok)return text;const data:any=await response.json();const translated=String(data.data?.translations?.[0]?.translatedText||'');return translated.replaceAll('&amp;','&').replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&quot;',String.fromCharCode(34)).replaceAll('&#39;',String.fromCharCode(39))||text;}catch{return text;}}

app.get('/health',async(_req,res)=>{if(!pool)return res.status(503).json({ok:false,service:'StreamVoice API',database:'not_configured'});try{await pool.query('SELECT 1');res.json({ok:true,service:'StreamVoice API',database:'connected'});}catch{res.status(503).json({ok:false,service:'StreamVoice API',database:'unavailable'});}});
app.get('/api/system/infrastructure',(_req,res)=>res.json({ok:true,provider:'standalone',databaseProvider:'PostgreSQL',secretsExposed:false}));
app.get('/api/languages',(_req,res)=>res.json({languages}));
app.post('/api/auth/signup',authRateLimit,needsDb,async(req,res,next)=>{try{
const email=String(req.body?.email||'').trim().toLowerCase(),username=String(req.body?.username||'').trim(),password=String(req.body?.password||''),language=String(req.body?.preferredLanguage||'en');
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254)return fail(res,400,'SV-AUTH-001','Enter a valid email address.');
if(!/^[A-Za-z0-9_]{3,24}$/.test(username))return fail(res,400,'SV-AUTH-002','Username must be 3-24 characters using letters, numbers, or underscores.');
if(password.length<8||password.length>128)return fail(res,400,'SV-AUTH-003','Password must be 8-128 characters.');
if(!languages.some(x=>x.code===language))return fail(res,400,'SV-AUTH-004','Unsupported preferred language.');
const salt=randomBytes(16).toString('hex'),digest=await hashPassword(password,salt),id=randomUUID(),client=await pool!.connect();
try{await client.query('BEGIN');const ins=await client.query('INSERT INTO sv_accounts(id,email,email_key,username,username_key,password_salt,password_hash,preferred_language) VALUES($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT DO NOTHING RETURNING id',[id,email,normalizeEmail(email),username,normalizeUsername(username),salt,digest,language]);if(!ins.rowCount){const c=await client.query('SELECT email_key=$1 AS email_conflict FROM sv_accounts WHERE email_key=$1 OR username_key=$2 LIMIT 1',[normalizeEmail(email),normalizeUsername(username)]);await client.query('ROLLBACK');return fail(res,409,c.rows[0]?.email_conflict?'SV-AUTH-005':'SV-AUTH-006',c.rows[0]?.email_conflict?'An account with that email already exists.':'That username is already taken.');}await client.query('INSERT INTO sv_chat_settings(user_id,enabled,language) VALUES($1,true,$2)',[id,language]);await client.query('COMMIT');}catch(e){await client.query('ROLLBACK').catch(()=>undefined);throw e;}finally{client.release();}
const token=await newSession(id);setCookie(res,token,maxAge);return res.status(201).json({ok:true,user:{username,email,preferredLanguage:language}});
}catch(e){next(e);}});
app.post('/api/auth/login',authRateLimit,needsDb,async(req,res,next)=>{try{const identifier=String(req.body?.identifier||'').trim(),password=String(req.body?.password||'');if(!identifier||!password||password.length>128)return fail(res,400,'SV-AUTH-007','Enter your username or email and password.');const key=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(identifier)?normalizeEmail(identifier):normalizeUsername(identifier);const q=await pool!.query('SELECT id,email,username,password_salt,password_hash,preferred_language FROM sv_accounts WHERE (email_key=$1 OR username_key=$1) AND deleted_at IS NULL LIMIT 1',[key]);const a=q.rows[0],candidate=a?await hashPassword(password,a.password_salt):'';if(!a||!equalHex(candidate,a.password_hash))return fail(res,401,'SV-AUTH-009','Invalid username/email or password.');const token=await newSession(a.id);setCookie(res,token,maxAge);return res.json({ok:true,user:{username:a.username,email:a.email,preferredLanguage:a.preferred_language}});}catch(e){next(e);}});
app.post('/api/auth/logout',needsDb,async(req,res,next)=>{try{const token=cookie(req,'streamvoice_session');if(token)await pool!.query('DELETE FROM sv_sessions WHERE token_hash=$1',[tokenHash(token)]);setCookie(res,'',0);res.json({ok:true});}catch(e){next(e);}});
app.get('/api/auth/me',needsDb,auth,(req,res)=>{if(!req.svUser)return fail(res,401,'SV-AUTH-010','Your StreamVoice session is missing or expired. Please log in again.');res.json({user:{username:req.svUser.username,email:req.svUser.email,preferredLanguage:req.svUser.preferredLanguage},session:{active:true,persistent:true}});});

function requireUser(req:Request,res:Response){if(!req.svUser){fail(res,401,'SV-AUTH-010','Please log in again.');return null;}return req.svUser;}
const bridgeHash=(code:string)=>createHash('sha256').update(code.trim().toUpperCase()).digest('hex');
const pairingCodeRateLimit=rateLimit({windowMs:60_000,limit:10,standardHeaders:'draft-7',legacyHeaders:false,message:{error:'Too many pairing-code requests. Wait a minute and try again.',code:'SV-BS-429'}});
app.post('/api/beat-saber/pair-code',pairingCodeRateLimit,needsDb,async(req,res,next)=>{try{await pool!.query('DELETE FROM sv_beat_saber_pairing_codes WHERE expires_at<now() OR claimed_at<now()-interval \'15 minutes\'');const gameVersion=String(req.body?.gameVersion||'').slice(0,40),modVersion=String(req.body?.modVersion||'').slice(0,40);for(let attempt=0;attempt<10;attempt++){const code=String(randomInt(0,100000)).padStart(5,'0'),insert=await pool!.query('INSERT INTO sv_beat_saber_pairing_codes(code_hash,expires_at,game_version,mod_version) VALUES($1,now()+interval \'5 minutes\',$2,$3) ON CONFLICT DO NOTHING RETURNING code_hash',[bridgeHash(code),gameVersion,modVersion]);if(insert.rowCount)return res.status(201).json({ok:true,pairingCode:code,expiresAt:Date.now()+300000,protocol:'streamvoice-bs/2',gameVersion,modVersion});}return fail(res,503,'SV-BS-003','Could not allocate a pairing code. Try again.');}catch(e){next(e);}});
app.get('/api/beat-saber/pair-status',needsDb,async(req,res,next)=>{try{const code=String(req.query.code||'').trim();if(!/^\d{5}$/.test(code))return fail(res,400,'SV-BS-001','A five-digit pairing code is required.');const q=await pool!.query('SELECT claimed_user_id,expires_at FROM sv_beat_saber_pairing_codes WHERE code_hash=$1',[bridgeHash(code)]);if(!q.rowCount)return fail(res,404,'SV-BS-004','Pairing code was not found.');res.json({ok:true,claimed:Boolean(q.rows[0].claimed_user_id),expired:new Date(q.rows[0].expires_at).getTime()<=Date.now(),expiresAt:new Date(q.rows[0].expires_at).getTime(),protocol:'streamvoice-bs/2'});}catch(e){next(e);}});
app.post('/api/beat-saber/claim-code',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const code=String(req.body?.code||req.body?.pairingCode||'').trim();if(!/^\d{5}$/.test(code))return fail(res,400,'SV-BS-001','Enter the five-digit code shown in Beat Saber.');const claimed=await pool!.query('UPDATE sv_beat_saber_pairing_codes SET claimed_user_id=$2,claimed_at=now() WHERE code_hash=$1 AND expires_at>now() AND claimed_user_id IS NULL RETURNING game_version,mod_version',[bridgeHash(code),u.id]);if(!claimed.rowCount){const existing=await pool!.query('SELECT claimed_user_id,expires_at FROM sv_beat_saber_pairing_codes WHERE code_hash=$1',[bridgeHash(code)]);if(!existing.rowCount||new Date(existing.rows[0].expires_at).getTime()<=Date.now())return fail(res,410,'SV-BS-005','Pairing code expired. Generate a new code in Beat Saber.');if(existing.rows[0].claimed_user_id!==u.id)return fail(res,409,'SV-BS-006','This pairing code has already been claimed.');}const details=claimed.rows[0]||{game_version:'',mod_version:''};await pool!.query('INSERT INTO sv_beat_saber_bridges(user_id,pairing_code_hash,connected,game_version,mod_version) VALUES($1,$2,false,$3,$4) ON CONFLICT(user_id) DO UPDATE SET pairing_code_hash=EXCLUDED.pairing_code_hash,connected=false,last_seen=NULL,game_version=EXCLUDED.game_version,mod_version=EXCLUDED.mod_version,updated_at=now()',[u.id,bridgeHash(code),details.game_version,details.mod_version]);res.json({ok:true,paired:true,connected:false,protocol:'streamvoice-bs/2'});}catch(e){next(e);}});
app.get('/api/account/settings',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const q=await pool!.query('SELECT email,username,preferred_language FROM sv_accounts WHERE id=$1',[u.id]);const a=q.rows[0];res.json({email:a.email,username:a.username,preferredLanguage:a.preferred_language});}catch(e){next(e);}});
app.post('/api/account/preferences',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const language=String(req.body?.preferredLanguage||'en');if(!languages.some(x=>x.code===language))return fail(res,400,'SV-SET-001','Unsupported language.');await pool!.query('UPDATE sv_accounts SET preferred_language=$2,updated_at=now() WHERE id=$1',[u.id,language]);await pool!.query('UPDATE sv_chat_settings SET language=$2,updated_at=now() WHERE user_id=$1',[u.id,language]);res.json({ok:true,preferredLanguage:language});}catch(e){next(e);}});
app.post('/api/account/email',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const email=String(req.body?.email||'').trim().toLowerCase(),password=String(req.body?.currentPassword||'');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return fail(res,400,'SV-SET-002','Enter a valid email.');const q=await pool!.query('SELECT password_salt,password_hash FROM sv_accounts WHERE id=$1',[u.id]);if(!q.rowCount||!equalHex(await hashPassword(password,q.rows[0].password_salt),q.rows[0].password_hash))return fail(res,401,'SV-SET-003','Current password is incorrect.');try{await pool!.query('UPDATE sv_accounts SET email=$2,email_key=$3,updated_at=now() WHERE id=$1',[u.id,email,normalizeEmail(email)]);}catch(e:any){if(e?.code==='23505')return fail(res,409,'SV-SET-004','That email is already in use.');throw e;}res.json({ok:true,email});}catch(e){next(e);}});
app.post('/api/account/password',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const current=String(req.body?.currentPassword||''),nextPassword=String(req.body?.newPassword||'');if(nextPassword.length<8||nextPassword.length>128)return fail(res,400,'SV-SET-005','New password must be 8-128 characters.');const q=await pool!.query('SELECT password_salt,password_hash FROM sv_accounts WHERE id=$1',[u.id]);if(!q.rowCount||!equalHex(await hashPassword(current,q.rows[0].password_salt),q.rows[0].password_hash))return fail(res,401,'SV-SET-003','Current password is incorrect.');const salt=randomBytes(16).toString('hex'),digest=await hashPassword(nextPassword,salt);await pool!.query('UPDATE sv_accounts SET password_salt=$2,password_hash=$3,updated_at=now() WHERE id=$1',[u.id,salt,digest]);await pool!.query('DELETE FROM sv_sessions WHERE user_id=$1',[u.id]);setCookie(res,'',0);res.json({ok:true,message:'Password changed. Please log in again.'});}catch(e){next(e);}});
app.post('/api/account/delete',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;if(String(req.body?.confirmation||'')!=='DELETE')return fail(res,400,'SV-SET-006','Type DELETE to confirm.');const q=await pool!.query('SELECT password_salt,password_hash FROM sv_accounts WHERE id=$1',[u.id]);if(!q.rowCount||!equalHex(await hashPassword(String(req.body?.currentPassword||''),q.rows[0].password_salt),q.rows[0].password_hash))return fail(res,401,'SV-SET-003','Current password is incorrect.');await pool!.query('DELETE FROM sv_accounts WHERE id=$1',[u.id]);setCookie(res,'',0);res.json({ok:true});}catch(e){next(e);}});
app.get('/api/stream-settings',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const q=await pool!.query('SELECT tts_enabled AS "ttsEnabled",read_messages AS "readMessages",read_gifts AS "readGifts",voice,speech_rate AS rate,volume FROM sv_stream_preferences WHERE user_id=$1',[u.id]);res.json(q.rows[0]||{ttsEnabled:true,readMessages:true,readGifts:true,voice:'Calm',rate:0.9,volume:0.72});}catch(e){next(e);}});
app.put('/api/stream-settings',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const ttsEnabled=req.body?.ttsEnabled!==false,readMessages=req.body?.readMessages!==false,readGifts=req.body?.readGifts!==false,voice=String(req.body?.voice||'Calm'),rate=Number(req.body?.rate??0.9),volume=Number(req.body?.volume??0.72);if(!['Calm','Neutral','Warm'].includes(voice)||!Number.isFinite(rate)||rate<0.6||rate>1.4||!Number.isFinite(volume)||volume<0||volume>1)return fail(res,400,'SV-STREAM-001','Invalid TTS preferences.');const q=await pool!.query('INSERT INTO sv_stream_preferences(user_id,tts_enabled,read_messages,read_gifts,voice,speech_rate,volume) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(user_id) DO UPDATE SET tts_enabled=EXCLUDED.tts_enabled,read_messages=EXCLUDED.read_messages,read_gifts=EXCLUDED.read_gifts,voice=EXCLUDED.voice,speech_rate=EXCLUDED.speech_rate,volume=EXCLUDED.volume,updated_at=now() RETURNING tts_enabled AS "ttsEnabled",read_messages AS "readMessages",read_gifts AS "readGifts",voice,speech_rate AS rate,volume',[u.id,ttsEnabled,readMessages,readGifts,voice,rate,volume]);res.json(q.rows[0]);}catch(e){next(e);}});

app.get('/api/chat-settings',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const q=await pool!.query('SELECT enabled,language FROM sv_chat_settings WHERE user_id=$1',[u.id]);res.json({...q.rows[0],languages});}catch(e){next(e);}});
app.put('/api/chat-settings',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const language=String(req.body?.language||'en'),enabled=req.body?.enabled!==false;if(!languages.some(x=>x.code===language))return fail(res,400,'SV-CHAT-001','Unsupported language.');await pool!.query('INSERT INTO sv_chat_settings(user_id,enabled,language) VALUES($1,$2,$3) ON CONFLICT(user_id) DO UPDATE SET enabled=EXCLUDED.enabled,language=EXCLUDED.language,updated_at=now()',[u.id,enabled,language]);res.json({enabled,language,languages});}catch(e){next(e);}});
app.get('/api/tts-blocked-words',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const q=await pool!.query('SELECT word FROM sv_blocked_words WHERE user_id=$1 ORDER BY word',[u.id]);res.json({words:q.rows.map(x=>x.word)});}catch(e){next(e);}});
app.put('/api/tts-blocked-words',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const words=Array.isArray(req.body?.words)?[...new Set(req.body.words.map((x:unknown)=>String(x).trim().toLowerCase()).filter((x:string)=>x&&x.length<=100))].slice(0,100):[];const client=await pool!.connect();try{await client.query('BEGIN');await client.query('DELETE FROM sv_blocked_words WHERE user_id=$1',[u.id]);for(const word of words)await client.query('INSERT INTO sv_blocked_words(user_id,word) VALUES($1,$2) ON CONFLICT DO NOTHING',[u.id,word]);await client.query('COMMIT');}catch(e){await client.query('ROLLBACK');throw e;}finally{client.release();}res.json({words});}catch(e){next(e);}});
app.get('/api/chat/unified',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const after=Number(req.query.after||0);const q=await pool!.query('SELECT id,platform,author,message AS text,message_type AS type,event_kind AS kind,extract(epoch from created_at)*1000 AS "createdAt" FROM sv_unified_chat WHERE user_id=$1 AND extract(epoch from created_at)*1000>$2 ORDER BY created_at DESC LIMIT 100',[u.id,Number.isFinite(after)?after:0]);res.json({messages:q.rows.reverse()});}catch(e){next(e);}});
app.get('/api/stream-state',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const q=await pool!.query('SELECT platform,channel_name,is_live FROM sv_platform_connections WHERE user_id=$1',[u.id]);const platforms:any={TikTok:{connected:false,live:false,channel:'Not connected'},YouTube:{connected:false,live:false,channel:'Not connected'},Twitch:{connected:false,live:false,channel:'Not connected'}};for(const r of q.rows)platforms[r.platform]={connected:true,live:r.is_live,channel:r.channel_name||r.platform};res.json({user:{signedIn:true,name:u.username},platforms});}catch(e){next(e);}});
app.get('/api/integrations/config',(_req,res)=>res.json({YouTube:Boolean(process.env.YOUTUBE_CLIENT_ID&&process.env.YOUTUBE_CLIENT_SECRET),Twitch:Boolean(process.env.TWITCH_CLIENT_ID&&process.env.TWITCH_CLIENT_SECRET),TikTok:Boolean(process.env.TIKTOK_CLIENT_KEY&&process.env.TIKTOK_CLIENT_SECRET),Translation:Boolean(process.env.GOOGLE_TRANSLATE_API_KEY)}));
for(const platform of ['tiktok','youtube','twitch']){app.get('/api/'+platform+'/status',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const q=await pool!.query('SELECT channel_name,is_live FROM sv_platform_connections WHERE user_id=$1 AND platform=$2',[u.id,platform[0].toUpperCase()+platform.slice(1)]);res.json({configured:Boolean(platformCredentials(platform).id&&platformCredentials(platform).secret),connected:Boolean(q.rowCount),live:Boolean(q.rows[0]?.is_live),channel:q.rows[0]?.channel_name||'Not connected'});}catch(e){next(e);}});app.post('/api/'+platform+'/disconnect',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;await pool!.query('DELETE FROM sv_platform_connections WHERE user_id=$1 AND platform=$2',[u.id,platform[0].toUpperCase()+platform.slice(1)]);res.json({ok:true,connected:false});}catch(e){next(e);}});}
app.get('/api/youtube/chat',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const q=await pool!.query('SELECT * FROM sv_platform_connections WHERE user_id=$1 AND platform=\'YouTube\'',[u.id]);if(!q.rowCount)return res.json({messages:[],pollingIntervalMillis:5000,connected:false});const connection=q.rows[0],credentials=platformCredentials('youtube');if(!credentials.id||!credentials.secret)return fail(res,503,'SV-OAUTH-001','YouTube OAuth credentials are not configured.');let accessToken=decryptToken(String(connection.access_token||'')),refreshToken=connection.refresh_token?decryptToken(String(connection.refresh_token)):'',expiresAt=connection.token_expires_at?new Date(connection.token_expires_at).getTime():0;if(expiresAt<Date.now()+60000){if(!refreshToken)return fail(res,401,'SV-OAUTH-007','YouTube authorization expired. Disconnect and reconnect YouTube.');const refreshed=await fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:credentials.id,client_secret:credentials.secret,refresh_token:refreshToken,grant_type:'refresh_token'})});const token:any=await refreshed.json();if(!refreshed.ok||!token.access_token)return fail(res,401,'SV-OAUTH-007','YouTube token refresh failed. Reconnect YouTube.');accessToken=token.access_token;expiresAt=Date.now()+Number(token.expires_in||3600)*1000;await pool!.query('UPDATE sv_platform_connections SET access_token=$3,token_expires_at=$4,updated_at=now() WHERE user_id=$1 AND platform=$2',[u.id,'YouTube',encryptToken(accessToken),new Date(expiresAt)]);}
const broadcastsResponse=await fetch('https://www.googleapis.com/youtube/v3/liveBroadcasts?part=snippet&broadcastStatus=active&mine=true',{headers:{Authorization:'Bearer '+accessToken}});const broadcasts:any=await broadcastsResponse.json();if(!broadcastsResponse.ok)return fail(res,502,'SV-YT-001','YouTube live status request failed.');const liveChatId=String(broadcasts.items?.[0]?.snippet?.liveChatId||'');await pool!.query('UPDATE sv_platform_connections SET is_live=$2,updated_at=now() WHERE user_id=$1 AND platform=\'YouTube\'',[u.id,Boolean(liveChatId)]);if(!liveChatId)return res.json({messages:[],pollingIntervalMillis:5000,live:false});const params=new URLSearchParams({part:'snippet,authorDetails',liveChatId,maxResults:'200'});if(req.query.pageToken)params.set('pageToken',String(req.query.pageToken));const chatResponse=await fetch('https://www.googleapis.com/youtube/v3/liveChat/messages?'+params,{headers:{Authorization:'Bearer '+accessToken}});const chatData:any=await chatResponse.json();if(!chatResponse.ok)return fail(res,502,'SV-YT-002','YouTube live chat request failed.');const blocked=await pool!.query('SELECT word FROM sv_blocked_words WHERE user_id=$1',[u.id]);const blockedWords=blocked.rows.map((r:any)=>String(r.word).toLowerCase());const messages:any[]=[];for(const item of chatData.items||[]){const id=String(item.id||''),originalText=String(item.snippet?.displayMessage||''),author=String(item.authorDetails?.displayName||'YouTube viewer'),createdAt=Date.parse(String(item.snippet?.publishedAt||''))||Date.now();if(!id||!originalText||blockedWords.some((word:string)=>word&&originalText.toLowerCase().includes(word)))continue;const text=await translateForUser(u.id,originalText);if(blockedWords.some((word:string)=>word&&text.toLowerCase().includes(word)))continue;const message={id,platform:'YouTube',author,text,type:'textMessageEvent',createdAt};await pool!.query('INSERT INTO sv_unified_chat(id,user_id,platform,author,message,message_type,created_at) VALUES($1,$2,$3,$4,$5,$6,to_timestamp($7/1000.0)) ON CONFLICT(user_id,id) DO NOTHING',[id,u.id,'YouTube',author,text,'textMessageEvent',createdAt]);messages.push(message);const bridge=await pool!.query('SELECT 1 FROM sv_beat_saber_bridges WHERE user_id=$1',[u.id]);if(bridge.rowCount)await pool!.query('INSERT INTO sv_beat_saber_events(user_id,event_type,payload) VALUES($1,$2,$3)',[u.id,'chat',message]);}res.json({messages,nextPageToken:chatData.nextPageToken||'',pollingIntervalMillis:Number(chatData.pollingIntervalMillis||5000),live:true});}catch(e){next(e);}});

