app.get('/api/beat-saber/connect',needsDb,async(req,res,next)=>{try{const code=String(req.query.code||req.query.pairingCode||'').trim().toUpperCase();if(!/^\d{5}$/.test(code))return fail(res,401,'SV-BS-001','A five-digit pairing code is required.');const after=Number(req.query.after||0);const q=await pool!.query('UPDATE sv_beat_saber_bridges SET connected=true,last_seen=now(),game_version=$2,mod_version=$3,updated_at=now() WHERE pairing_code_hash=$1 RETURNING user_id',[bridgeHash(code),String(req.query.gameVersion||''),String(req.query.modVersion||'')]);if(!q.rowCount)return fail(res,403,'SV-BS-002','Invalid pairing code.');const events=await pool!.query('SELECT id::text AS id,event_type AS type,payload,floor(extract(epoch from created_at)*1000)::double precision AS "createdAt" FROM sv_beat_saber_events WHERE user_id=$1 AND acked_at IS NULL ORDER BY id LIMIT 25',[q.rows[0].user_id]);const latestCreatedAt=events.rows.reduce((latest:any,event:any)=>Math.max(latest,Number(event.createdAt||0)),0);res.json({ok:true,paired:true,events:events.rows,eventCount:events.rowCount,pendingCount:events.rowCount,dbCandidateCount:events.rowCount,requestedAfter:Number.isFinite(after)?after:0,latestCreatedAt,serverTime:Date.now(),protocol:'streamvoice-bs/2'});}catch(e){next(e);}});
app.get('/api/beat-saber/heartbeat',needsDb,async(req,res,next)=>{try{const code=String(req.query.code||req.query.pairingCode||'').trim().toUpperCase();if(!code)return fail(res,401,'SV-BS-001','Pairing code required.');const q=await pool!.query('UPDATE sv_beat_saber_bridges SET connected=true,last_seen=now(),game_version=$2,mod_version=$3,updated_at=now() WHERE pairing_code_hash=$1 RETURNING user_id',[bridgeHash(code),String(req.query.gameVersion||''),String(req.query.modVersion||'')]);if(!q.rowCount)return fail(res,403,'SV-BS-002','Invalid pairing code.');res.json({ok:true,connected:true,serverTime:Date.now(),protocol:'streamvoice-bs/2'});}catch(e){next(e);}});
app.post('/api/beat-saber/heartbeat',needsDb,async(req,res,next)=>{try{const code=String(req.body?.code||req.body?.pairingCode||'').trim().toUpperCase();if(!code)return fail(res,401,'SV-BS-001','Pairing code required.');const q=await pool!.query('UPDATE sv_beat_saber_bridges SET connected=true,last_seen=now(),game_version=$2,mod_version=$3,updated_at=now() WHERE pairing_code_hash=$1 RETURNING user_id',[bridgeHash(code),String(req.body?.gameVersion||''),String(req.body?.modVersion||'')]);if(!q.rowCount)return fail(res,403,'SV-BS-002','Invalid pairing code.');res.json({ok:true,connected:true,serverTime:Date.now(),protocol:'streamvoice-bs/2'});}catch(e){next(e);}});
app.post('/api/beat-saber/chat',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const text=String(req.body?.text||'').trim().slice(0,1000),author=String(req.body?.author||'Viewer').slice(0,120),platform=String(req.body?.platform||'StreamVoice');if(!text)return fail(res,400,'SV-CHAT-002','Message cannot be empty.');const blocked=await pool!.query('SELECT word FROM sv_blocked_words WHERE user_id=$1',[u.id]);const translatedText=await translateForUser(u.id,text);if(blocked.rows.some((r:any)=>text.toLowerCase().includes(r.word)||translatedText.toLowerCase().includes(r.word)))return fail(res,422,'SV-MOD-001','Message rejected by blocked-word moderation.');const id=randomUUID();await pool!.query('INSERT INTO sv_unified_chat(id,user_id,platform,author,message,message_type) VALUES($1,$2,$3,$4,$5,$6)',[id,u.id,['Twitch','YouTube','TikTok','StreamVoice'].includes(platform)?platform:'StreamVoice',author,translatedText,'textMessageEvent']);const bridge=await pool!.query('SELECT user_id FROM sv_beat_saber_bridges WHERE user_id=$1',[u.id]);if(bridge.rowCount)await pool!.query('INSERT INTO sv_beat_saber_events(user_id,event_type,payload) VALUES($1,$2,$3)',[u.id,'chat',{id,author,text:translatedText,platform}]);res.json({ok:true,id});}catch(e){next(e);}});
async function queueTestChat(req:Request,res:Response,next:NextFunction){try{const u=requireUser(req,res);if(!u)return;const id=randomUUID(),payload={id,author:'StreamVoice Test',text:'StreamVoice test message',platform:'StreamVoice'};await pool!.query('INSERT INTO sv_unified_chat(id,user_id,platform,author,message,message_type) VALUES($1,$2,$3,$4,$5,$6)',[id,u.id,'StreamVoice',payload.author,payload.text,'textMessageEvent']);const bridge=await pool!.query('SELECT 1 FROM sv_beat_saber_bridges WHERE user_id=$1',[u.id]);let eventId:number|null=null;if(bridge.rowCount){const event=await pool!.query('INSERT INTO sv_beat_saber_events(user_id,event_type,payload) VALUES($1,$2,$3) RETURNING id',[u.id,'chat',payload]);eventId=Number(event.rows[0].id);}res.json({ok:true,queued:Boolean(bridge.rowCount),outboxCount:bridge.rowCount?1:0,eventId:eventId?String(eventId):'none',message:bridge.rowCount?'Test chat queued for the paired mod.':'Test chat saved; pair the mod to deliver it.'});}catch(e){next(e);}}
