app.post('/api/tiktok/webhook',async(req,res,next)=>{try{const raw=(req as Request & {rawBody?:string}).rawBody||'',signature=String(req.headers['tiktok-signature']||''),credentials=platformCredentials('tiktok');if(!credentials.secret)return fail(res,503,'SV-TT-001','TikTok webhook credentials are not configured.');const parts=signature.split(','),timestamp=parts.find(x=>x.startsWith('t='))?.slice(2)||'',provided=parts.find(x=>x.startsWith('s='))?.slice(2)||'';const age=Math.abs(Date.now()/1000-Number(timestamp));if(!timestamp||!provided||!Number.isFinite(age)||age>300)return fail(res,401,'SV-TT-002','Invalid or expired TikTok webhook signature.');const expected=createHmac('sha256',credentials.secret).update(timestamp+'.'+raw).digest('hex');if(!equalText(expected,provided))return fail(res,401,'SV-TT-002','Invalid TikTok webhook signature.');const payload=req.body||{};if(payload.challenge)return res.json({challenge:payload.challenge});const openId=String(payload.user_openid||payload.open_id||''),eventName=String(payload.event||'unknown');if(!openId)return res.json({ok:true,ignored:true});const connection=await pool?.query('SELECT user_id FROM sv_platform_connections WHERE platform=\'TikTok\' AND platform_user_id=$1',[openId]);if(!connection?.rowCount)return res.json({ok:true,ignored:true});const userId=connection.rows[0].user_id;if(eventName==='authorization.removed'){await pool!.query('DELETE FROM sv_platform_connections WHERE user_id=$1 AND platform=\'TikTok\'',[userId]);return res.json({ok:true,disconnected:true});}let content:any=payload.content||{};if(typeof content==='string'){try{content=JSON.parse(content);}catch{content={text:content};}}const commentText=String(content.comment||content.text||content.message||'').trim();if(eventName.toLowerCase().includes('comment')&&commentText){const blocked=await pool!.query('SELECT word FROM sv_blocked_words WHERE user_id=$1',[userId]);const translatedText=await translateForUser(userId,commentText);if(!blocked.rows.some((row:any)=>commentText.toLowerCase().includes(String(row.word).toLowerCase())||translatedText.toLowerCase().includes(String(row.word).toLowerCase()))){const id=String(payload.event_id||payload.id||randomUUID()),author=String(payload.user_name||payload.nickname||'TikTok Viewer').slice(0,120),createdAt=Number(payload.create_time||Date.now()/1000)*1000,message={id,platform:'TikTok',author,text:translatedText,type:'textMessageEvent',createdAt};await pool!.query('INSERT INTO sv_unified_chat(id,user_id,platform,author,message,message_type,created_at) VALUES($1,$2,$3,$4,$5,$6,to_timestamp($7/1000.0)) ON CONFLICT(user_id,id) DO NOTHING',[id,userId,'TikTok',author,translatedText,'textMessageEvent',createdAt]);await pool!.query('INSERT INTO sv_beat_saber_events(user_id,event_type,payload) SELECT $1,$2,$3 WHERE EXISTS(SELECT 1 FROM sv_beat_saber_bridges WHERE user_id=$1)',[userId,'chat',message]);}}else{const lowerEvent=eventName.toLowerCase(),kind=lowerEvent.includes('gift')?'gift':lowerEvent.includes('follow')?'follow':lowerEvent.includes('live')?'live':'';if(!kind)return res.json({ok:true,ignored:true});const author=String(content.user_name||payload.user_name||payload.nickname||'TikTok Viewer').slice(0,120),detail=kind==='gift'?String(content.gift_name||content.gift||'a gift'):kind==='follow'?'followed':'live event',text=author+' '+(kind==='gift'?'sent ':kind==='follow'?'':'')+detail,eventId=String(payload.event_id||payload.id||randomUUID()),createdAt=Date.now(),eventMessage={id:eventId,platform:'TikTok',author,text,type:'streamEvent',kind,createdAt};await pool!.query('INSERT INTO sv_unified_chat(id,user_id,platform,author,message,message_type,event_kind) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(user_id,id) DO NOTHING',[eventId,userId,'TikTok',author,text,'streamEvent',kind]);await pool!.query('INSERT INTO sv_beat_saber_events(user_id,event_type,payload) SELECT $1,$2,$3 WHERE EXISTS(SELECT 1 FROM sv_beat_saber_bridges WHERE user_id=$1)',[userId,'chat',eventMessage]);}res.json({ok:true});}catch(e){next(e);}});
app.post('/api/twitch/eventsub',async(req,res,next)=>{try{const messageType=String(req.headers['twitch-eventsub-message-type']||''),messageId=String(req.headers['twitch-eventsub-message-id']||''),timestamp=String(req.headers['twitch-eventsub-message-timestamp']||''),provided=String(req.headers['twitch-eventsub-message-signature']||''),payload=req.body||{};const broadcasterId=String(payload.event?.broadcaster_user_id||payload.subscription?.condition?.broadcaster_user_id||payload.event?.to_broadcaster_user_id||'');if(!broadcasterId)return fail(res,400,'SV-TW-001','Twitch EventSub payload is missing its broadcaster ID.');const q=await pool?.query('SELECT user_id,metadata FROM sv_platform_connections WHERE platform=\'Twitch\' AND platform_user_id=$1',[broadcasterId]);if(!q?.rowCount)return res.json({ok:true,ignored:true});const encryptedSecret=String(q.rows[0].metadata?.eventSubSecret||'');if(!encryptedSecret)return fail(res,503,'SV-TW-002','Twitch EventSub signing secret is not configured.');const secret=decryptToken(encryptedSecret),age=Math.abs(Date.now()-Date.parse(timestamp));if(!messageId||!timestamp||!provided||!Number.isFinite(age)||age>10*60*1000)return fail(res,401,'SV-TW-003','Invalid or expired Twitch EventSub signature.');const expected='sha256='+createHmac('sha256',secret).update(messageId+timestamp+((req as Request & {rawBody?:string}).rawBody||'')).digest('hex');if(!equalText(expected,provided))return fail(res,401,'SV-TW-003','Invalid Twitch EventSub signature.');if(messageType==='webhook_callback_verification')return res.type('text/plain').send(String(payload.challenge||''));if(messageType==='revocation')return res.json({ok:true,revoked:true});if(messageType!=='notification')return res.json({ok:true,ignored:true});const event=payload.event||{},userId=q.rows[0].user_id,eventType=String(payload.subscription?.type||'');if(eventType==='channel.chat.message'){const text=String(event.message?.text||'').trim(),author=String(event.chatter_user_name||event.chatter_user_login||'Twitch Viewer').slice(0,120),id=String(event.message_id||messageId);if(text){const blocked=await pool!.query('SELECT word FROM sv_blocked_words WHERE user_id=$1',[userId]);const translatedText=await translateForUser(userId,text);if(!blocked.rows.some((row:any)=>text.toLowerCase().includes(String(row.word).toLowerCase())||translatedText.toLowerCase().includes(String(row.word).toLowerCase()))){const createdAt=Date.now(),message={id,platform:'Twitch',author,text:translatedText,type:'textMessageEvent',createdAt};await pool!.query('INSERT INTO sv_unified_chat(id,user_id,platform,author,message,message_type) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(user_id,id) DO NOTHING',[id,userId,'Twitch',author,translatedText,'textMessageEvent']);await pool!.query('INSERT INTO sv_beat_saber_events(user_id,event_type,payload) SELECT $1,$2,$3 WHERE EXISTS(SELECT 1 FROM sv_beat_saber_bridges WHERE user_id=$1)',[userId,'chat',message]);}}}else{const lowerEvent=eventType.toLowerCase(),kind=lowerEvent.includes('follow')?'follow':lowerEvent.includes('gift')||lowerEvent.includes('subscribe')?'gift':'live',author=String(event.user_name||event.user_login||event.chatter_user_name||'Twitch Viewer').slice(0,120),detail=kind==='follow'?'followed':kind==='gift'?'subscribed or gifted':'live event',text=author+' '+detail,eventId=String(event.message_id||payload.subscription?.id||randomUUID()),createdAt=Date.now(),eventMessage={id:eventId,platform:'Twitch',author,text,type:'streamEvent',kind,createdAt};await pool!.query('INSERT INTO sv_unified_chat(id,user_id,platform,author,message,message_type,event_kind) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(user_id,id) DO NOTHING',[eventId,userId,'Twitch',author,text,'streamEvent',kind]);await pool!.query('INSERT INTO sv_beat_saber_events(user_id,event_type,payload) SELECT $1,$2,$3 WHERE EXISTS(SELECT 1 FROM sv_beat_saber_bridges WHERE user_id=$1)',[userId,'chat',eventMessage]);}res.json({ok:true});}catch(e){next(e);}});

app.get('/api/sounds/:platform/:kind',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const q=await pool!.query('SELECT filename,content_type,bytes FROM sv_sound_assets WHERE user_id=$1 AND platform=$2 AND event_kind=$3',[u.id,req.params.platform,req.params.kind]);if(!q.rowCount)return fail(res,404,'SV-SOUND-004','Sound not found.');res.setHeader('Cache-Control','private, max-age=300');res.type(q.rows[0].content_type).send(q.rows[0].bytes);}catch(e){next(e);}});
