app.post('/api/sounds/upload',needsDb,auth,async(req,res,next)=>{try{const u=requireUser(req,res);if(!u)return;const platform=String(req.body?.platform||''),kind=String(req.body?.kind||''),filename=String(req.body?.filename||'sound').slice(0,180),contentType=String(req.body?.contentType||'audio/mpeg'),base64=String(req.body?.base64||'');if(!['TikTok','YouTube','Twitch'].includes(platform)||!['gift','follow','live','subscription'].includes(kind))return fail(res,400,'SV-SOUND-001','Invalid platform or sound event.');if(!contentType.startsWith('audio/'))return fail(res,400,'SV-SOUND-002','Only audio files are allowed.');if(!base64||base64.length>7_000_000)return fail(res,413,'SV-SOUND-003','Audio file is empty or exceeds the 5 MB limit.');const bytes=Buffer.from(base64,'base64');if(!bytes.length||bytes.length>5*1024*1024)return fail(res,413,'SV-SOUND-003','Audio file is empty or exceeds the 5 MB limit.');const id=randomUUID();await pool!.query('INSERT INTO sv_sound_assets(id,user_id,platform,event_kind,filename,content_type,bytes) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(user_id,platform,event_kind) DO UPDATE SET filename=EXCLUDED.filename,content_type=EXCLUDED.content_type,bytes=EXCLUDED.bytes,created_at=now()',[id,u.id,platform,kind,filename,contentType,bytes]);res.json({ok:true,url:'/api/sounds/'+platform+'/'+kind,filename});}catch(e){next(e);}});
function readAdminToken(req:Request){return cookie(req,'streamvoice_admin_session');}
async function requireAdmin(req:Request,res:Response){const token=readAdminToken(req);if(!token||!pool){fail(res,401,'SV-ADMIN-001','Administrator login required.');return false;}const q=await pool.query('SELECT 1 FROM sv_admin_sessions WHERE token_hash=$1 AND expires_at>now()',[tokenHash(token)]);if(!q.rowCount){fail(res,401,'SV-ADMIN-001','Administrator login required.');return false;}return true;}
app.post('/api/admin/login',needsDb,authRateLimit,async(req,res,next)=>{try{const username=String(req.body?.username||''),password=String(req.body?.password||'');if(!process.env.ADMIN_USERNAME||!process.env.ADMIN_PASSWORD)return fail(res,503,'SV-ADMIN-002','Administrator credentials are not configured in server environment.');if(!equalText(username,process.env.ADMIN_USERNAME)||!equalText(password,process.env.ADMIN_PASSWORD))return fail(res,401,'SV-ADMIN-003','Invalid administrator credentials.');const token=randomBytes(32).toString('base64url');await pool!.query('INSERT INTO sv_admin_sessions(id,token_hash,expires_at) VALUES($1,$2,now()+interval \'8 hours\')',[randomUUID(),tokenHash(token)]);res.setHeader('Set-Cookie',`streamvoice_admin_session=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Strict; Max-Age=28800${production?'; Secure':''}`);res.json({ok:true});}catch(e){next(e);}});
app.post('/api/admin/logout',needsDb,async(req,res,next)=>{try{const token=readAdminToken(req);if(token)await pool!.query('DELETE FROM sv_admin_sessions WHERE token_hash=$1',[tokenHash(token)]);res.setHeader('Set-Cookie',`streamvoice_admin_session=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0${production?'; Secure':''}`);res.json({ok:true});}catch(e){next(e);}});
app.get('/api/admin/overview',needsDb,async(req,res,next)=>{try{if(!await requireAdmin(req,res))return;const accounts=await pool!.query('SELECT id,email,username,created_at FROM sv_accounts WHERE deleted_at IS NULL ORDER BY created_at DESC LIMIT 250');const counts=await pool!.query('SELECT platform,count(*)::int AS count FROM sv_platform_connections GROUP BY platform');const countMap:any={};for(const r of counts.rows)countMap[r.platform]=r.count;const audit=await pool!.query('SELECT id,actor,action,extract(epoch from created_at)*1000 AS "createdAt" FROM sv_admin_audit ORDER BY created_at DESC LIMIT 50');const tableNames=['sv_accounts','sv_sessions','sv_chat_settings','sv_stream_preferences','sv_blocked_words','sv_platform_connections','sv_beat_saber_bridges','sv_beat_saber_events','sv_bsr_requests','sv_unified_chat','sv_sound_assets'];const tables:any[]=[];for(const name of tableNames){const count=await pool!.query('SELECT count(*)::int AS count FROM '+name);tables.push({name,count:count.rows[0].count});}res.json({stats:{accounts:accounts.rowCount,tiktok:countMap.TikTok||0,youtube:countMap.YouTube||0,twitch:countMap.Twitch||0},tables,users:accounts.rows.map(a=>({id:a.id,email:a.email,username:a.username,createdAt:new Date(a.created_at).getTime()})),audit:audit.rows});}catch(e){next(e);}});
app.get('/api/admin/users/:id',needsDb,async(req,res,next)=>{try{if(!await requireAdmin(req,res))return;const q=await pool!.query('SELECT id,email,username,created_at FROM sv_accounts WHERE id=$1 AND deleted_at IS NULL',[req.params.id]);if(!q.rowCount)return fail(res,404,'SV-ADMIN-004','Account not found.');res.json({user:{...q.rows[0],createdAt:new Date(q.rows[0].created_at).getTime()}});}catch(e){next(e);}});
app.post('/api/admin/users/:id/disconnect/:platform',needsDb,async(req,res,next)=>{try{if(!await requireAdmin(req,res))return;const platform=String(req.params.platform).toLowerCase(),value=platform==='tiktok'?'TikTok':platform==='youtube'?'YouTube':platform==='twitch'?'Twitch':'';if(!value)return fail(res,400,'SV-ADMIN-005','Invalid platform.');await pool!.query('DELETE FROM sv_platform_connections WHERE user_id=$1 AND platform=$2',[req.params.id,value]);await pool!.query('INSERT INTO sv_admin_audit(actor,action,target_user_id) VALUES($1,$2,$3)',[process.env.ADMIN_USERNAME||'admin','disconnect_'+platform,req.params.id]);res.json({ok:true});}catch(e){next(e);}});
app.post('/api/admin/users/:id/unpair-beatsaber',needsDb,async(req,res,next)=>{try{if(!await requireAdmin(req,res))return;await pool!.query('DELETE FROM sv_beat_saber_bridges WHERE user_id=$1',[req.params.id]);await pool!.query('INSERT INTO sv_admin_audit(actor,action,target_user_id) VALUES($1,$2,$3)',[process.env.ADMIN_USERNAME||'admin','unpair_beatsaber',req.params.id]);res.json({ok:true});}catch(e){next(e);}});

app.use((req,res)=>fail(res,404,'SV-ROUTE-404',`Route not implemented: ${req.method} ${req.path}`));
app.use((err:unknown,_req:Request,res:Response,_next:NextFunction)=>{console.error('StreamVoice API request failed:',err instanceof Error?err.message:'unknown error');fail(res,500,'SV-SERVER-500','The server could not complete the request.');});
if(process.env.NODE_ENV!=='test'){const host=process.env.HOST||'127.0.0.1';const server=app.listen(port,host,()=>console.log(`StreamVoice API listening on ${host}:${port}`));const stop=async()=>{server.close();if(pool)await pool.end();process.exit(0);};process.on('SIGTERM',stop);process.on('SIGINT',stop);}
export {app,pool};